var status = -1;
var viewKind = 0;       // 0=普通时装 1=属性时装
var viewTypeIdx = -1;   // -1=全部类型
var viewPage = 0;
var flatAllCache = null;
var statedCache = null;
var repeatedMsg = "";   // 一次开启的临时结果显示

function resolveItemId() {
    for (var i = 0; i < ITEM_IDS.length; i++) {
        if (im.haveItem(ITEM_IDS[i], 1)) {
            return ITEM_IDS[i];
        }
    }
    return 0;
}

function itemName(itemId) {
    try {
        var n = ItemInformationProvider.getInstance().getName(itemId);
        if (n != null && n.length() > 0) {
            return String(n);
        }
    } catch (e) {}
    return "时装#" + itemId;
}

function getFlatAll() {
    if (flatAllCache != null) {
        return flatAllCache;
    }
    var all = [];
    for (var i = 0; i < TYPE_POOLS.length; i++) {
        var flat = TYPE_POOLS[i].flat;
        for (var j = 0; j < flat.length; j++) {
            all.push({ id: flat[j], typeName: TYPE_POOLS[i].name, rare: TYPE_POOLS[i].rare });
        }
    }
    flatAllCache = all;
    return all;
}

function getStatedAll() {
    if (statedCache != null) {
        return statedCache;
    }
    var all = [];
    for (var i = 0; i < TYPE_POOLS.length; i++) {
        var st = TYPE_POOLS[i].stated;
        for (var j = 0; j < st.length; j++) {
            all.push({
                id: st[j].id,
                score: st[j].score,
                weight: st[j].weight > 0 ? st[j].weight : 1,
                typeName: TYPE_POOLS[i].name,
                rare: TYPE_POOLS[i].rare
            });
        }
    }
    statedCache = all;
    return all;
}

function pickWeighted(list, weightOf) {
    if (list.length === 0) {
        return null;
    }
    var total = 0;
    for (var i = 0; i < list.length; i++) {
        total += weightOf(list[i]);
    }
    if (total <= 0) {
        return list[0];
    }
    var roll = Math.random() * total;
    for (var j = 0; j < list.length; j++) {
        roll -= weightOf(list[j]);
        if (roll < 0) {
            return list[j];
        }
    }
    return list[list.length - 1];
}

/* ---------- 持久化（按角色） ---------- */
function readExt(key, def) {
    try {
        var v = im.getCharacterExtendValue(key);
        if (v != null && String(v).length > 0) {
            var n = parseInt(String(v), 10);
            return isNaN(n) ? def : n;
        }
    } catch (e) {}
    return def;
}

function getTotal() { return readExt(EXT_TOTAL, 0); }
function getLuck()  { return readExt(EXT_LUCK, 0); }

function saveTotal(n) { try { im.saveOrUpdateCharacterExtendValue(EXT_TOTAL, String(n)); } catch (e) {} }
function saveLuck(n)  { try { im.saveOrUpdateCharacterExtendValue(EXT_LUCK, String(n)); } catch (e) {} }

/* 幸运条：按 Login.img/Notice/Loading/bar/0~9 的 10 帧分段，bar/10 为背景 */
function luckBar(luck) {
    var pct = Math.min(100, Math.max(0, Math.round(luck * 100.0 / LUCK_THRESHOLD)));
    var filled = Math.min(10, Math.floor(pct / 10));
    var bar = "";
    for (var i = 0; i < 10; i++) {
        bar += i < filled ? "#b▓#k" : "#d░#k";
    }
    return bar + " " + pct + "%";
}

function appendLog(line) {
    try {
        var File = Java.type("java.io.File");
        var logDir = new File("logs/xz2461");
        if (!logDir.exists()) { logDir.mkdirs(); }
        var FileWriter = Java.type("java.io.FileWriter");
        var fw = new FileWriter(new File(logDir, "xz2461.log"), true);
        fw.write(line + "\r\n");
        fw.close();
    } catch (e) {
        try { im.getPlayer().dropMessage(1, "log:" + line); } catch (e2) {}
    }
}

/* ---------- 抽取 ---------- */
function doOpen(n) {
    var boxId = resolveItemId();
    if (boxId === 0) {
        im.sendOk("盲盒道具数量不足。");
        im.dispose();
        return;
    }
    var have = im.getItemQuantity(boxId);
    if (have < n) {
        im.sendOk("当前只有 #b" + have + "#k 个盲盒，无法一次开启 #r" + n + "#k 个。");
        return;
    }

    var statedPool = getStatedAll();
    var flatPool = getFlatAll();
    if (statedPool.length === 0 || flatPool.length === 0) {
        im.sendOk("盲盒奖池未配置。");
        im.dispose();
        return;
    }

    im.gainItem(boxId, -n);
    var luck = getLuck();
    var total = getTotal();
    var results = [];

    for (var i = 0; i < n; i++) {
        luck++;
        var guaranteed = (luck >= LUCK_THRESHOLD);
        var e;
        if (guaranteed) {
            // 第 LUCK_THRESHOLD 个必定命中属性池，随后幸运重置
            e = pickWeighted(statedPool, function (x) { return x.weight; });
            luck = 0;
        } else {
            if (Math.random() * 100 < FLAT_PCT) {
                e = flatPool[Math.floor(Math.random() * flatPool.length)];
            } else {
                e = pickWeighted(statedPool, function (x) { return x.weight; });
            }
        }
        total++;
        var hasStat = (e.score !== undefined && e.score > 0);
        // 有属性 → randomizeStats(标准属性上下波动)；无属性(白板) → 不随机
        im.gainItem(e.id, 1, hasStat, true);
        results.push({
            id: e.id,
            hasStat: hasStat,
            guaranteed: guaranteed,
            score: hasStat ? e.score : 0,
            typeName: e.typeName,
            rare: e.rare
        });

        if (hasStat) {
            var txt = "[惊喜盲盒2460010] " + im.getPlayer().getName() + " 抽中了" + e.typeName + "：" + itemName(e.id) +
                (guaranteed ? "（保底）" : "") + "！属性分 " + e.score + "！";
            im.getPlayer().getWorldServer().broadcastPacket(PacketCreator.serverNotice(6, txt));
            appendLog(txt);
        }
    }

    saveTotal(total);
    saveLuck(luck);

    var statCount = 0;
    var text = "#e#b惊喜盲盒 · 开启结果#k#n（本次 " + n + " 个）\r\n\r\n";
    for (var k = 0; k < results.length; k++) {
        var r = results[k];
        if (r.hasStat) {
            statCount++;
            text += "#r[属性]#k #v" + r.id + "# #t" + r.id + "#  " + r.typeName +
                "  属性分:#r" + r.score + "#k" + (r.guaranteed ? "  #r【保底】#k" : "") + "\r\n";
        } else {
            text += "#b[普通]#k #v" + r.id + "# #t" + r.id + "#\r\n";
        }
    }
    text += "\r\n本次命中属性时装：#r" + statCount + "#k 件\r\n";
    text += "累计已开启：#b" + total + "#k 个\r\n\r\n";
    im.sendOk(text);
}

/* ---------- 主界面 ---------- */
function showMain() {
    if (resolveItemId() === 0) {
        im.sendOk("盲盒道具数量不足。");
        im.dispose();
        return;
    }
    var have = im.getItemQuantity(ITEM_IDS[0]);
    var total = getTotal();
    var luck = getLuck();
    var statedN = getStatedAll().length;
    var flatN = getFlatAll().length;

    var text = "#e#b惊喜盲盒 2460010#k#n\r\n\r\n";
    text += "#e第 1 行#n  当前拥有：#b" + have + "#k 个  |  累计已开启：#b" + total + "#k 个\r\n";
    text += "#e幸运进度#n  " + luckBar(luck) + "\r\n";
    text += "#d        抽奖次数 #b" + luck + "#k / " + LUCK_THRESHOLD + "（满 " + LUCK_THRESHOLD + " 必出属性时装）\r\n";
    text += "#d        奖池：无属性时装 #b" + flatN + "#k 件（98%）/ 有属性时装 #r" + statedN + "#k 件（2%）#k\r\n\r\n";
    text += "#L0##r开启 1 个#k\r\n";
    text += "#L1##b开启 10 个#k\r\n";
    text += "#L2##b奖品预览·普通时装#k\r\n";
    text += "#L3##r奖品预览·属性时装#k\r\n";
    text += "#L4#关闭#l";
    im.sendSimple(text);
}

/* ---------- 预览：选择类型（含全部） ---------- */
function showTypeFilter() {
    var text = (viewKind === 0 ? "普通时装（白板）" : "#r属性时装（悬停图标可看装备属性）") + "#k · 选择部位\r\n\r\n";
    text += "#L0#全部类型#l\r\n";
    for (var i = 0; i < TYPE_POOLS.length; i++) {
        text += "#L" + (i + 1) + "#" + TYPE_POOLS[i].name + "#l\r\n";
    }
    im.sendSimple(text);
}

/* ---------- 分页列表(图标每行10个、每页5行=50个) ---------- */
var PER_ROW = 10;
var ROWS_PER_PAGE = 5;

function showPreviewList() {
    var ids = [];
    if (viewKind === 0) {
        var flat = getFlatAll();
        for (var f = 0; f < flat.length; f++) {
            if (viewTypeIdx < 0 || TYPE_POOLS[viewTypeIdx].name === flat[f].typeName) {
                ids.push(flat[f].id);
            }
        }
    } else {
        var st = getStatedAll();
        for (var s = 0; s < st.length; s++) {
            if (viewTypeIdx < 0 || TYPE_POOLS[viewTypeIdx].name === st[s].typeName) {
                ids.push(st[s].id);
            }
        }
    }
    var perPage = PER_ROW * ROWS_PER_PAGE;
    var totalPages = Math.max(1, Math.ceil(ids.length / perPage));
    if (viewPage >= totalPages) { viewPage = totalPages - 1; }
    if (viewPage < 0) { viewPage = 0; }

    var title = (viewKind === 0 ? "普通时装" : "#r属性时装#k") +
        " · " + (viewTypeIdx < 0 ? "全部" : TYPE_POOLS[viewTypeIdx].name) +
        "  " + (viewPage + 1) + "/" + totalPages + "（悬停图标看装备详情）\r\n\r\n";
    var text = "#e" + title + "#n";
    var idx = viewPage * perPage;
    for (var r = 0; r < ROWS_PER_PAGE; r++) {
        for (var c = 0; c < PER_ROW; c++) {
            if (idx < ids.length) {
                text += "#v" + ids[idx] + "# ";
                idx++;
            }
        }
        text += "\r\n";
    }
    if (ids.length === 0) {
        text += "#r该部位暂无此类时装。#k\r\n";
    }
    text += "\r\n";
    if (viewPage > 0) { text += "#L90#上一页#l  "; }
    if (viewPage < totalPages - 1) { text += "#L91#下一页#l  "; }
    text += "#L92#返回#l";
    im.sendSimple(text);
}

function start() {
    status = -1;
    viewKind = 0;
    viewTypeIdx = -1;
    viewPage = 0;
    action(1, 0, 0);
}

function action(mode, type, selection) {
    if (mode == -1) {
        im.dispose();
        return;
    }
    // 开启结果对话框( sendOk )：点确定回到主菜单
    if (status == -1) {
        if (mode == 1) { status = 0; showMain(); }
        else { im.dispose(); }
        return;
    }
    if (status == 0) {
        if (mode == 0) { im.dispose(); return; }
        if (selection == 0) { doOpen(1); status = -1; }
        else if (selection == 1) { doOpen(10); status = -1; }
        else if (selection == 2) { viewKind = 0; viewTypeIdx = -1; viewPage = 0; status = 1; showTypeFilter(); }
        else if (selection == 3) { viewKind = 1; viewTypeIdx = -1; viewPage = 0; status = 1; showTypeFilter(); }
        else { im.dispose(); }
        return;
    }
    if (status == 1) {
        viewTypeIdx = selection - 1;   // 0=全部(-1)，1..N=具体类型
        viewPage = 0;
        status = 2;
        showPreviewList();
        return;
    }
    if (status == 2) {
        if (mode == 0) { status = 0; showMain(); return; }
        if (selection == 90 && viewPage > 0) { viewPage--; showPreviewList(); return; }
        if (selection == 91) { viewPage++; showPreviewList(); return; }
        status = 0; showMain(); return;
    }
    im.dispose();
}
